    "tool_params": {
      "path": "parse_kv.py",
      "content": "import re

def parse_kv(s: str) -> dict:
    """
    Parses a string like 'key1=value1; key2=value2' into a dictionary.
    Semicolons separate pairs, first '=' separates key from value. 
    Keys and values are whitespace-trimmed. A backslash-escaped semicolon \; 
    is a literal semicolon in a value. Empty string yields an empty dict.
    """
    if not s:
        return {}

    # Split by semicolon ONLY if it is not preceded by a backslash
    pairs = re.split(r'(?<!\\);', s)

    result = {}

    for pair_str in pairs:
        pair_str = pair_str.strip()
        if not pair_str:
            continue

        if '=' in pair_str:
            key, value = pair_str.split('=', 1)

            # Clean up key and value
            key = key.strip()
            value = value.strip()

            # Handle escaping: replace literal \; with ;
            # Note: We need to handle both \; and \; depending on how Python interprets the input string.
            # Assuming the input string literal uses \; to represent the sequence '\;' in the value.
            # Based on typical string parsing, a literal sequence `\;` should result in `;`.
            value = value.replace('\;', ';')

            result[key] = value

    return result
