from parse_kv import parse_kv

class TestParseKV(unittest.TestCase):
    def test_empty_string(self):
        self.assertEqual(parse_kv(""), {})

    def test_standard_parsing(self):
        self.assertEqual(parse_kv("key1=value1; key2=value2"), {"key1": "value1", "key2": "value2"})

    def test_whitespace_trimming(self):
        self.assertEqual(parse_kv("  k1 = v1 ; k2= v2  "), {"k1": "v1", "k2": "v2"})

    def test_escaped_semicolon(self):
        # The sequence \; should result in a literal semicolon ; in the value
        # Input string: key=val\;ue; next_key=next_val
        self.assertEqual(parse_kv("key=val\;ue; next_key=next_val"), {"key": "val;ue", "next_key": "next_val"})

    def test_multiple_semicolons(self):
        # Test multiple escaped semicolons
        self.assertEqual(parse_kv("k=v\;e\;at"), {"k": "v;e;at"})

    def test_leading_trailing_semicolons(self):
        # Should ignore empty segments resulting from leading/trailing delimiters
        self.assertEqual(parse_kv(";k1=v1;"), {"k1": "v1"})

    def test_only_whitespace(self):
        self.assertEqual(parse_kv(" 
 	 "), {})

if __name__ == '__main__':
    unittest.main()
